<?php if ($result['rows']): ?><div class="removal-confirm"><label for="admin-password">Votre mot de passe administrateur</label><input id="admin-password" name="admin_password" type="password" autocomplete="current-password" required maxlength="1024"><label><input type="checkbox" name="confirm" value="1" required> Je confirme la sélection et ses conséquences</label><button class="primary" type="submit" data-confirm="Confirmer le traitement des éléments sélectionnés ? Les suppressions définitives sont irréversibles." onclick="return confirm('Confirmer le traitement des éléments sélectionnés ? Les suppressions définitives sont irréversibles.')">Traiter la sélection</button></div><?php endif; ?></form>
